export function initWeatherFavorites({root,db,esc,onSelect,getPlace}){
 let uid=null,rows=[],epoch=0,busy=false,message='';
 const key=p=>`${Number(p.latitude).toFixed(3)},${Number(p.longitude).toFixed(3)}`;
 function render(){const p=getPlace(),saved=p&&rows.some(r=>r.place_key===key(p));root.innerHTML=`<h3>Mis lugares</h3><button id="weather-save" ${busy||!p?'disabled':''}>${uid?(saved?'★ Quitar de favoritos':'☆ Guardar lugar'):'Ingresar para guardar favoritos'}</button><p role="status">${esc(message)}</p><div class="weather-favorites-list">${rows.map((r,i)=>`<button data-weather-favorite="${i}"><strong>${esc(r.name)}</strong><small>${esc(r.region)}</small></button>`).join('')}</div>${uid?'<small>Privados · sincronizados con tu cuenta de Convergencia</small>':''}`;
 root.querySelector('#weather-save').onclick=async()=>{if(!uid){document.getElementById('feed-account')?.click();return;}const p=getPlace();if(!p||busy)return;const owner=uid,token=epoch;busy=true;message='Guardando…';render();const query=db.from('atlas_dev_weather_favorites');let result;try{result=saved?await query.delete().eq('user_id',owner).eq('place_key',key(p)):await query.upsert({user_id:owner,place_key:key(p),name:p.name,region:p.region||'',latitude:p.latitude,longitude:p.longitude,timezone:p.timezone||'UTC'},{onConflict:'user_id,place_key'});if(token!==epoch)return;if(result.error)throw result.error;message=saved?'Lugar quitado de favoritos.':'Guardado en tu cuenta.';await refresh();}catch{if(token===epoch)message='No se pudo guardar. Reintenta.';}finally{if(token===epoch){busy=false;render();}}};
 root.querySelectorAll('[data-weather-favorite]').forEach(b=>b.onclick=()=>onSelect(rows[Number(b.dataset.weatherFavorite)]));}
 async function refresh(){if(!uid)return;const token=epoch,owner=uid;try{const {data,error}=await db.from('atlas_dev_weather_favorites').select('place_key,name,region,latitude,longitude,timezone').eq('user_id',owner).order('created_at');if(token!==epoch)return;if(error)throw error;rows=data||[];render();}catch{if(token===epoch){message='No se pudieron sincronizar tus lugares. Reintenta al volver a Clima.';render();}}}
 function session(user){const next=user?.id||null;if(next===uid)return;epoch++;uid=next;rows=[];busy=false;message='';render();if(uid)refresh();}
 if(db){db.auth.getSession().then(({data})=>session(data?.session?.user));db.auth.onAuthStateChange((_,s)=>setTimeout(()=>session(s?.user),0));}render();document.addEventListener('visibilitychange',()=>{if(!document.hidden)refresh();});return {render,refresh};
}
